import { EventEmitter } from 'events';
import * as crypto from 'crypto';

interface CacheEntry {
  value: Buffer;
  ttl: number;
  createdAt: number;
}

interface FeatureFlags {
  enableCompression: boolean;
  enableEncryption: boolean;
  maxRetries: number;
  consistencyLevel: 'eventual' | 'strong';
}

class DistributedCacheClient extends EventEmitter {
  private cache: Map<string, CacheEntry> = new Map();
  private flags: FeatureFlags;
  private connectionState: 'connected' | 'disconnected' | 'reconnecting' = 'disconnected';
  private pendingOps: Array<{ resolve: Function; reject: Function; op: string }> = [];
  private shutdownInProgress = false;
  private flushPromise: Promise<void> | null = null;
  private operationCounter = 0;
  private readonly encryptionKey: Buffer;

  constructor(flags: FeatureFlags) {
    super();
    this.flags = flags;
    this.encryptionKey = crypto.randomBytes(32);
    this.setupSignalHandlers();
  }

  private setupSignalHandlers(): void {
    const gracefulShutdown = async (signal: string) => {
      if (this.shutdownInProgress) return;
      this.shutdownInProgress = true;
      this.emit('shutdown-start', signal);
      await this.flushPendingWrites();
      this.connectionState = 'disconnected';
      this.emit('shutdown-complete');
    };

    process.on('SIGTERM', () => gracefulShutdown('SIGTERM'));
    process.on('SIGINT', () => gracefulShutdown('SIGINT'));
    process.on('SIGUSR1', () => this.reloadFeatureFlags());
  }

  private async reloadFeatureFlags(): Promise<void> {
    const newFlags = await this.fetchRemoteFlags();
    this.flags = newFlags;
    this.emit('flags-reloaded', newFlags);
  }

  private async fetchRemoteFlags(): Promise<FeatureFlags> {
    return new Promise((resolve) => {
      setTimeout(() => {
        resolve({
          enableCompression: true,
          enableEncryption: false,
          maxRetries: 5,
          consistencyLevel: 'eventual'
        });
      }, 100);
    });
  }

  async connect(): Promise<void> {
    this.connectionState = 'connected';
    this.emit('connected');
  }

  async set(key: string, value: Buffer, ttl: number = 3600): Promise<boolean> {
    if (this.shutdownInProgress) {
      throw new Error('Client is shutting down');
    }

    this.operationCounter++;
    const processedValue = await this.processValue(value, 'encode');

    const entry: CacheEntry = {
      value: processedValue,
      ttl,
      createdAt: Date.now()
    };

    if (this.flags.consistencyLevel === 'strong') {
      await this.replicateToQuorum(key, entry);
    }

    this.cache.set(key, entry);
    return true;
  }

  async get(key: string): Promise<Buffer | null> {
    const entry = this.cache.get(key);
    if (!entry) return null;

    const now = Date.now();
    if (now - entry.createdAt > entry.ttl * 1000) {
      this.cache.delete(key);
      return null;
    }

    const decodedValue = await this.processValue(entry.value, 'decode');
    return decodedValue;
  }

  private async processValue(value: Buffer, direction: 'encode' | 'decode'): Promise<Buffer> {
    let result = value;

    if (this.flags.enableEncryption) {
      if (direction === 'encode') {
        result = this.encrypt(result);
      } else {
        result = this.decrypt(result);
      }
    }

    return result;
  }

  private encrypt(data: Buffer): Buffer {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv('aes-256-gcm', this.encryptionKey, iv);
    const encrypted = Buffer.concat([cipher.update(data), cipher.final()]);
    const authTag = cipher.getAuthTag();
    return Buffer.concat([iv, authTag, encrypted]);
  }

  private decrypt(data: Buffer): Buffer {
    const iv = data.subarray(0, 16);
    const authTag = data.subarray(16, 32);
    const encrypted = data.subarray(32);
    const decipher = crypto.createDecipheriv('aes-256-gcm', this.encryptionKey, iv);
    decipher.setAuthTag(authTag);
    return Buffer.concat([decipher.update(encrypted), decipher.final()]);
  }

  private async replicateToQuorum(key: string, entry: CacheEntry): Promise<void> {
    const replicaCount = 3;
    const promises = Array.from({ length: replicaCount }, (_, i) =>
      this.sendToReplica(i, key, entry)
    );
    const results = await Promise.allSettled(promises);
    const successes = results.filter(r => r.status === 'fulfilled').length;
    if (successes < Math.ceil(replicaCount / 2)) {
      throw new Error('Failed to achieve quorum');
    }
  }

  private async sendToReplica(replicaId: number, key: string, entry: CacheEntry): Promise<void> {
    await new Promise(resolve => setTimeout(resolve, 10));
  }

  private async flushPendingWrites(): Promise<void> {
    if (this.flushPromise) return this.flushPromise;

    this.flushPromise = new Promise<void>(async (resolve) => {
      const snapshot = new Map(this.cache);
      for (const [key, entry] of snapshot) {
        await this.persistEntry(key, entry);
      }
      this.pendingOps.forEach(op => op.reject(new Error('Shutdown')));
      this.pendingOps = [];
      resolve();
    });

    return this.flushPromise;
  }

  private async persistEntry(key: string, entry: CacheEntry): Promise<void> {
    await new Promise(resolve => setTimeout(resolve, 5));
  }

  getStats(): { entries: number; ops: number; state: string } {
    return {
      entries: this.cache.size,
      ops: this.operationCounter,
      state: this.connectionState
    };
  }
}

export { DistributedCacheClient, FeatureFlags };
